package net.atlasauth.pca.verifier

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The intent history primitives (the window test, the accumulator key, pre-state and post-state, the monitor step and state) against the reference
 * (base-intenthistory, 29179 cases; generated by the base intent-history oracle). Every result compares by JSON value. Where the reference throws,
 * accPreState and accPost return null and the other functions throw; where the reference's inWindow falls off its switch (undefined, falsy) the answer is false.
 */
@Suppress("UNCHECKED_CAST")
class BaseIntentHistoryDiffTest {
    private val mod = "base-intenthistory"
    private val mustThrow = 0
    private val throwIsNull = 1
    private val undefinedIsFalse = 2

    private fun map(o: Any?): Map<String, Any?> = o as Map<String, Any?>

    private fun mapOrNull(o: Any?): Map<String, Any?>? = o as? Map<String, Any?>

    private fun list(o: Any?): List<Any?> = o as List<Any?>

    private fun each(fn: String, mode: Int, f: (List<Any?>) -> Any?): Int {
        val cases = BaseOracle.cases("$mod.json.gz", fn)
        assertTrue("no oracle cases for $fn", cases.isNotEmpty())
        val bad = ArrayList<String>()
        for (c in cases) {
            var want = c["out"]
            var throwsWant = want is Map<*, *> && want.containsKey("\$throws")
            if (throwsWant && mode == throwIsNull) { want = null; throwsWant = false }
            if (want == null && mode == undefinedIsFalse) want = false
            var got: Any? = null
            var err: Throwable? = null
            try { got = f(c["args"] as List<Any?>) } catch (t: Throwable) { err = t }
            if (throwsWant) {
                if (err == null) bad.add("${c["name"]}\n  want: throw ${c["out"]}\n  got:  $got")
            } else if (err != null) {
                bad.add("${c["name"]}\n  want: $want\n  got:  THROWS $err")
            } else if (!IntentJs.jsonEquals(want, IntentJs.normalize(OracleCases.toJson(got)))) {
                bad.add("${c["name"]}\n  want: $want\n  got:  $got")
            }
        }
        assertTrue("${bad.size} of ${cases.size} divergent case(s) of $fn:\n" + bad.take(40).joinToString("\n"), bad.isEmpty())
        return cases.size
    }

    @Test fun everyFunction() {
        var total = 0
        total += each("inWindow", undefinedIsFalse) { a -> IntentHistory.inWindow(mapOrNull(a[0]), a[1], a[2]) }
        total += each("accKeyOf", mustThrow) { a ->
            val p = mapOrNull(a[1]) // a grouped key over non-object params reads nothing (null)
            if (p == null) { if (map(a[0])["key"] is String) null else "\u2022" } else IntentHistory.accKeyOf(map(a[0]), p)
        }
        total += each("accPreState", mustThrow) { a ->
            val cand = map(a[2])
            IntentHistory.accPreState(map(a[0]), list(a[1]), map(cand["params"]), cand["t"], a[3])
        }
        total += each("accPost", mustThrow) { a ->
            val cand = map(a[2])
            IntentHistory.accPost(map(a[0]), list(a[1]), cand["verb"] as String, map(cand["params"]), cand["t"], a[3])
        }
        total += each("monitorStep", mustThrow) { a -> IntentHistory.monitorStep(map(a[0]), a[1] as String, mapOrNull(a[2]) ?: throw IllegalArgumentException("no event")) }
        total += each("monitorState", mustThrow) { a -> IntentHistory.monitorState(map(a[0]), list(a[1])) }
        assertEquals(setOf("inWindow", "accKeyOf", "accPreState", "accPost", "monitorStep", "monitorState"), BaseOracle.fns("$mod.json.gz"))
        assertEquals(29179, total)
    }
}
